                ['url' => 'https://commons.wikimedia.org/wiki/File:Makam_Syekh_Subakir.jpg', 'caption' => ['Petilasan di Gunung Tidar yang banyak dikunjungi peziarah', 'A shrine on Mount Tidar visited by many pilgrims'], 'credit' => $commons],
